652	    struct ufunc_traits<Func, void(Args...), std::index_sequence<I...>> {
653	        static constexpr char types[sizeof...(Args)] = {npy_typenum_v<Args>...};
654	
655	        static constexpr size_t ranks[sizeof...(Args)] = {rank_of_v<Args>...};
656	
657	        static constexpr size_t ranks_scan[sizeof...(Args) + 1] = {
658	            detail::initializer_accumulate(ranks, ranks + I, 0)...,
659	            detail::initializer_accumulate(ranks, ranks + sizeof...(Args), 0)
660	        };
