662	        static void loop(char **args, const npy_intp *dims, const npy_intp *steps, void *data) {
663	            std::array<npy_intp, ranks_scan[sizeof...(Args)]> new_dims;
664	
665	            map_dims_type map_dims = static_cast<ufunc_data<Func> *>(data)->map_dims;
666	            map_dims(dims + 1, new_dims.data());
667	
668	            Func func = static_cast<ufunc_data<Func> *>(data)->func;
669	            for (npy_intp i = 0; i < dims[0]; ++i) {
670	                func(npy_traits<Args>::get(
671	                    args[I], new_dims.data() + ranks_scan[I], steps + ranks_scan[I] + sizeof...(Args)
672	                )...);
673	
674	                for (npy_uintp j = 0; j < sizeof...(Args); ++j) {
675	                    args[j] += steps[j];
