699	            template <typename Func>
700	            SpecFun_Func(Func func)
701	                : has_return(has_return_v<Func>), nin_and_nout(arity_of_v<Func> + has_return),
702	                  func(ufunc_traits<Func>::loop), data(new ufunc_data<Func>{{nullptr}, func}),
703	                  data_deleter([](void *ptr) { delete static_cast<ufunc_data<Func> *>(ptr); }),
